// Más recientes primero. @todas = sin filtro de empresa (actor sistema); si no, empresa_id
// igual a la activa (null = modo sin conector).
func (q *Queries) ListarPendientes(ctx context.Context, arg ListarPendientesParams) ([]IntegracionPendiente, error) {
	rows, err := q.db.Query(ctx, listarPendientes,
		arg.DespuesDe,
		arg.Todas,
		arg.EmpresaID,
		arg.Entidad,
		arg.EntidadID,
		arg.Estado,
		arg.EstadoDistintoDe,
		arg.SoloConflicto,
		arg.Limite,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []IntegracionPendiente
	for rows.Next() {
		var i IntegracionPendiente
		if err := rows.Scan(
			&i.ID,
			&i.EmpresaID,
			&i.Sistema,
			&i.Operacion,
			&i.IdempotencyKey,
			&i.Entidad,
			&i.EntidadID,
			&i.Metodo,
			&i.Ruta,
			&i.Payload,
			&i.DependeDe,
			&i.DatosIncompletos,
			&i.Estado,
			&i.Intentos,
			&i.ProximoIntento,
			&i.TomadoEn,
			&i.UltimoError,
			&i.UltimoStatus,
			&i.HechoEn,
			&i.EventoID,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Conflicto,
			&i.ConflictoPayload,
			&i.ConflictoEn,
			&i.Respuesta,
			&i.Plantilla,
			&i.PorResolver,
			&i.Verificar,
			&i.TecnicoUsuarioID,
			&i.CodigoError,
			&i.ResueltoMotivo,
			&i.ResueltoPor,
			&i.ResueltoEn,
			&i.Actor,
			&i.TransitoID,
			&i.ResueltoComo,
			&i.ResueltoClienteID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

